            aWandererK = aWandererK + (((RotL64(aScatter, 39U) + aOrbiterH) + RotL64(aOrbiterF, 53U)) + aNonceWordO);
            aWandererD = aWandererD ^ (((RotL64(aPrevious, 37U) + aOrbiterD) + RotL64(aOrbiterG, 3U)) + aWUSaltE[((aIndex + 221U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aCross, 53U) + aOrbiterJ) + RotL64(aOrbiterI, 6U)) + aNonceWordM);
