    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xFDC85B027E3797F1ULL + 0xB18F7D4C529548DAULL);
