            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0x66A65F2ADDCED513ULL) + aOUSaltD[((aIndex + 117U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0xD5ED57CD663D5DABULL;
