            aCross = (RotL64(aCrystalLaneC[((S_BLOCK1 - aIndex + 3063U)) & S_BLOCK1], 43U) ^ RotL64(aCrystalLaneA[((S_BLOCK1 - aIndex + 6910U)) & S_BLOCK1], 27U));
