            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 5U) + RotL64(aCross, 28U)) + (RotL64(aPrevious, 41U) ^ RotL64(aCarry, 57U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterH = ((aWandererF + RotL64(aIngress, 57U)) + RotL64(aCarry, 23U)) + 0x3DE7E1450A481B97ULL;
            aOrbiterI = ((aWandererG + RotL64(aScatter, 6U)) + 0xEB88DB52A16EE624ULL) + aOASaltD[((aIndex + 329U)) & S_SALT1];
