            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x50CB6CF146BDE7F3ULL) + aOUSaltA[(((511U - aIndex) + 421U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0xAB4E20E38B9EDF34ULL;
