            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterA = (((aWandererJ + RotL64(aScatter, 60U)) + RotL64(aCarry, 13U)) + 0x9CD4228C10173AA1ULL) + aOASaltC[((aIndex + 250U)) & S_SALT1];
            aOrbiterB = (aWandererD + RotL64(aPrevious, 47U)) + 0x666FB1FDA239CB9AULL;
