            aWandererF = aWandererF ^ ((((RotL64(aPrevious, 21U) + RotL64(aOrbiterI, 53U)) + aOrbiterC) + RotL64(aCarry, 11U)) + aWUSaltB[((aIndex + 46U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aCross, 27U) + aOrbiterH) + RotL64(aOrbiterG, 43U)) + aWUSaltG[(((511U - aIndex) + 266U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aIngress, 53U) + aOrbiterK) + RotL64(aOrbiterA, 6U));
